<section class="page-head"><span class="eyebrow">DOCTOR PORTAL</span><h1>Availability & Slot Control</h1><p>Create weekly schedules, date-specific availability, busy blocks and leave.</p></section><form class="form-card wide" method="post"><div class="grid2"><label>Hospital<select name="hospital_id"><option value="">Any / Independent</option><?php foreach($hospitals as $h):?><option value="<?=$h['id']?>"><?=$h['name']?></option><?php endforeach?></select></label><label>Specific Date (optional)<input type="date" name="available_date"></label><label>Weekly Day<select name="day_of_week"><option value="">Date-specific</option><option value="1">Monday</option><option value="2">Tuesday</option><option value="3">Wednesday</option><option value="4">Thursday</option><option value="5">Friday</option><option value="6">Saturday</option><option value="0">Sunday</option></select></label><label>Status<select name="status"><option>available</option><option>busy</option><option>leave</option></select></label><label>Start Time<input type="time" name="start_time" required></label><label>End Time<input type="time" name="end_time" required></label><label>Slot Minutes<input type="number" name="slot_minutes" value="15" min="5"></label></div><button class="btn primary">Save Availability</button></form><section class="section"><div class="table-wrap"><table><tr><th>Hospital</th><th>Date/Day</th><th>Time</th><th>Status</th><th>Slot</th></tr><?php foreach($availability as $a):?><tr><td><?=$a['hospital']?:'Independent'?></td><td><?=$a['available_date']?:('Weekly day '.$a['day_of_week'])?></td><td><?=$a['start_time']?>–<?=$a['end_time']?></td><td><?=$a['status']?></td><td><?=$a['slot_minutes']?> min</td></tr><?php endforeach?></table></div></section>